CREATE TABLE IF NOT EXISTS users(id CHAR(36) PRIMARY KEY,username VARCHAR(100) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS roles(id CHAR(36) PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,description VARCHAR(255));
CREATE TABLE IF NOT EXISTS permissions(id CHAR(36) PRIMARY KEY,code VARCHAR(120) NOT NULL UNIQUE,description VARCHAR(255));
CREATE TABLE IF NOT EXISTS user_roles(user_id CHAR(36) NOT NULL,role_id CHAR(36) NOT NULL,PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS role_permissions(role_id CHAR(36) NOT NULL,permission_id CHAR(36) NOT NULL,PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS properties(id CHAR(36) PRIMARY KEY,building VARCHAR(100) NOT NULL,room VARCHAR(100) NOT NULL,status VARCHAR(30) NOT NULL,available_from DATETIME NOT NULL,UNIQUE(building,room),INDEX idx_property_available(status,available_from));
CREATE TABLE IF NOT EXISTS facilities(id CHAR(36) PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS property_facilities(property_id CHAR(36) NOT NULL,facility_id CHAR(36) NOT NULL,PRIMARY KEY(property_id,facility_id));
CREATE TABLE IF NOT EXISTS tenants(id CHAR(36) PRIMARY KEY,name VARCHAR(120) NOT NULL,phone VARCHAR(40),email VARCHAR(120),identity_no VARCHAR(80),status VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS leases(id CHAR(36) PRIMARY KEY,property_id CHAR(36) NOT NULL,tenant_id CHAR(36) NOT NULL,status VARCHAR(30) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,monthly_rent BIGINT NOT NULL,deposit BIGINT NOT NULL,INDEX idx_lease_range(property_id,start_date,end_date));
CREATE TABLE IF NOT EXISTS lease_versions(id CHAR(36) PRIMARY KEY,lease_id CHAR(36) NOT NULL,version_no INT NOT NULL,monthly_rent BIGINT NOT NULL,deposit BIGINT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,UNIQUE(lease_id,version_no));
CREATE TABLE IF NOT EXISTS bills(id CHAR(36) PRIMARY KEY,lease_id CHAR(36) NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL,amount BIGINT NOT NULL,penalty BIGINT NOT NULL DEFAULT 0,discount BIGINT NOT NULL DEFAULT 0,paid BIGINT NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL,UNIQUE(lease_id,period_start,period_end));
CREATE TABLE IF NOT EXISTS payments(id CHAR(36) PRIMARY KEY,bill_id CHAR(36) NOT NULL,reference VARCHAR(120) NOT NULL UNIQUE,amount BIGINT NOT NULL,paid_at TIMESTAMP NOT NULL,status VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS deposit_ledgers(id CHAR(36) PRIMARY KEY,lease_id CHAR(36) NOT NULL,kind VARCHAR(30) NOT NULL,reference VARCHAR(120) NOT NULL UNIQUE,amount BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS work_orders(id CHAR(36) PRIMARY KEY,property_id CHAR(36) NOT NULL,tenant_id CHAR(36),assignee_id CHAR(36),description TEXT NOT NULL,status VARCHAR(30) NOT NULL,material_cost BIGINT NOT NULL DEFAULT 0,tenant_confirmed BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS meter_readings(id CHAR(36) PRIMARY KEY,lease_id CHAR(36) NOT NULL,kind VARCHAR(40) NOT NULL,reading BIGINT NOT NULL,read_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS settlements(id CHAR(36) PRIMARY KEY,lease_id CHAR(36) NOT NULL UNIQUE,status VARCHAR(30) NOT NULL,total BIGINT NOT NULL,deposit_deduction BIGINT NOT NULL,refund BIGINT NOT NULL,settled_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id CHAR(36) PRIMARY KEY,actor_id CHAR(36),action VARCHAR(120) NOT NULL,resource VARCHAR(120) NOT NULL,resource_id VARCHAR(120),detail JSON,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
